//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::compare`; the
//! native twin is `benches/native/Bench/StringCompare.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::string;
use lean_runtime_bench::{mixed, run, step, SEED};
use std::hint::black_box;
#[allow(unused_variables)]
fn kernel(inp: &(String, String), n: u64) -> u64 {
    let (s, t) = (inp.0.as_bytes(), inp.1.as_bytes());
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add((string::compare(black_box(s), t) as i8 + 1) as u64);
    }
    acc as u64
}

fn main() {
    run(
        || {
            let s = mixed();
            let mut t = s.clone();
            t.pop();
            t.push('4');
            (s, t)
        },
        kernel,
    )
}
